//! CLI output compared with the C SQLite 3.54.1 shell (step 5h). GENERATED by
//! target/perf-work/step5h/gen/gen_cli_tests.py: the expected bytes are what `sqlite3` prints for the same
//! arguments and input.

use std::io::Write;
use std::process::{Command, Stdio};

fn run(args: &[&str], stdin: &[u8]) -> (Vec<u8>, Vec<u8>, i32) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_sqliters"))
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()
        .unwrap();
    child.stdin.take().unwrap().write_all(stdin).unwrap();
    let out = child.wait_with_output().unwrap();
    (out.stdout, out.stderr, out.status.code().unwrap_or(-1))
}

fn show(b: &[u8]) -> String {
    String::from_utf8_lossy(b).into_owned()
}

#[test]
fn errors_on_stdin() {
    let (out, err, rc) = run(
        &[":memory:"],
        b"create table t(a primary key, b);\ninsert into t values(1,2);\ninsert into t values(1,2);\nselect 1; select 2; select * from nosuch; select 3;\nselect zzz from t;\nselect abs(1,2);\nselect 1 +;\ncreate table t(x);\nselect x'zz';\n# comment\n   .print not-a-dot-command\nselect 5;\ninsert into t values(2,3),(3,4);\nselect a, case when a=3 then abs(-9223372036854775807-1) else a end from t order by a;\nselect (\n",
    );
    assert_eq!(show(&err), show(b"Error near line 3: UNIQUE constraint failed: t.a\nParse error near line 4: no such table: nosuch\nParse error near line 5: no such column: zzz\n  select zzz from t;\n         ^--- error here\nParse error near line 6: wrong number of arguments to function abs()\n  select abs(1,2);\n         ^--- error here\nParse error near line 7: near \";\": syntax error\n  select 1 +;\n            ^--- error here\nParse error near line 8: table t already exists\n  create table t(x);\n               ^--- error here\nParse error near line 9: unrecognized token: \"x'zz'\"\n  select x'zz';\n         ^--- error here\nParse error near line 11: near \".\": syntax error\n  .print not-a-dot-command select 5;\n  ^--- error here\nError near line 14: integer overflow\nParse error near line 15: incomplete input\n"));
    assert_eq!(out, b"1\n2\n1|1\n2|2\n", "{}", show(&out));
    assert_eq!(rc, 1);
}

#[test]
fn errors_in_arguments() {
    let (out, err, rc) = run(
        &[
            ":memory:",
            "select 1; select * from nosuch; select 3",
            "select 4",
        ],
        b"",
    );
    assert_eq!(
        show(&err),
        show(b"Parse error in 2nd command line argument: no such table: nosuch\n")
    );
    assert_eq!(out, b"1\n", "{}", show(&out));
    assert_eq!(rc, 1);
}

#[test]
fn cmd_errors_do_not_stop() {
    let (out, err, rc) = run(
        &[
            "-cmd",
            "select * from n1;",
            "-cmd",
            "select 77",
            ":memory:",
            "select 4",
        ],
        b"",
    );
    assert_eq!(
        show(&err),
        show(b"Parse error in 2nd command line argument: no such table: n1\n")
    );
    assert_eq!(out, b"77\n4\n", "{}", show(&out));
    assert_eq!(rc, 0);
}

#[test]
fn bail_stops_at_first_error() {
    let (out, err, rc) = run(
        &["-bail", ":memory:"],
        b"select 1;\nselect nosuch;\nselect 2;\n",
    );
    assert_eq!(show(&err), show(b"Parse error near line 2: no such column: nosuch\n  select nosuch;\n         ^--- error here\n"));
    assert_eq!(out, b"1\n", "{}", show(&out));
    assert_eq!(rc, 1);
}

#[test]
fn mode_list() {
    let (out, err, rc) = run(
        &["-list", ":memory:"],
        b"create table t(id integer primary key, name, r, b, n);\ninsert into t values(1,'alpha beta',1.5,x'000141ff',NULL),(2,'line1\nline2',1e100,x'',7),(3,'tab\x09here',-0.0,x'68656c6c6f',0.1),(4,char(1,65,27),2.0,x'7b7d',1e15),(5,'',9e999,x'41',' ');\nselect * from t;\nselect id from t where 0;\n",
    );
    assert_eq!(show(&err), show(b""));
    assert_eq!(out, b"1|alpha beta|1.5|^@^AA\xff|\n2|line1\nline2|1.0e+100||7\n3|tab\x09here|0.0|hello|0.1\n4|^AA^[|2.0|{}|1000000000000000.0\n5||Inf|A| \n", "{}", show(&out));
    assert_eq!(rc, 0);
}

