#[test]
fn mode_table() {
    let (out, err, rc) = run(
        &["-table", ":memory:"],
        b"create table t(id integer primary key, name, r, b, n);\ninsert into t values(1,'alpha beta',1.5,x'000141ff',NULL),(2,'line1\nline2',1e100,x'',7),(3,'tab\x09here',-0.0,x'68656c6c6f',0.1),(4,char(1,65,27),2.0,x'7b7d',1e15),(5,'',9e999,x'41',' ');\nselect * from t;\nselect id from t where 0;\n",
    );
    assert_eq!(show(&err), show(b""));
    assert_eq!(out, b"+----+--------------+----------+--------+--------------------+\n| id |     name     |    r     |   b    |         n          |\n+----+--------------+----------+--------+--------------------+\n|  1 | alpha beta   |      1.5 | ^@^AA\xff |                    |\n+----+--------------+----------+--------+--------------------+\n|  2 | line1        | 1.0e+100 |        |                  7 |\n|    | line2        |          |        |                    |\n+----+--------------+----------+--------+--------------------+\n|  3 | tab     here |      0.0 | hello  |                0.1 |\n+----+--------------+----------+--------+--------------------+\n|  4 | ^AA^[        |      2.0 | {}     | 1000000000000000.0 |\n+----+--------------+----------+--------+--------------------+\n|  5 |              |      Inf | A      |                    |\n+----+--------------+----------+--------+--------------------+\n+----+\n| id |\n+----+\n", "{}", show(&out));
    assert_eq!(rc, 0);
}

