#[test]
fn incremental_vacuum_rows() {
    let (out, err, rc) = run(
        &[":memory:"],
        b"pragma auto_vacuum=incremental;\ncreate table t(a);\ninsert into t values(zeroblob(3000)),(zeroblob(3000)),(zeroblob(3000));\ndelete from t;\nselect 'a';\npragma incremental_vacuum(2);\nselect 'b';\n",
    );
    assert_eq!(show(&err), show(b""));
    assert_eq!(out, b"a\n\n\nb\n", "{}", show(&out));
    assert_eq!(rc, 0);
}
